   out.push({level:'watch',title:'Spending is running higher',detail:`Recorded spending is ${delta.toFixed(0)}% higher than the previous comparable period (${money(cur.spent)} vs ${money(old.spent)}). ${drivers.length?'Largest contributors: '+drivers.map(x=>`${x.name} (+${money(x.value-x.prior)})`).join(' and ')+'.':'Review the largest recent transactions to identify the drivers.'}`,prompt:'Explain why my spending is higher and what I should do'});
