  budgets.forEach(b=>{if(b.planned>0&&b.nature!=='positive'){const projected=b.spent/pace;if((b.spent>=b.planned*.8&&elapsed<daysInMonth)||(projected>b.planned*1.1&&b.spent<b.planned)){out.push({level:'risk',title:`${b.category} budget needs attention`,detail:`${money(b.spent)} used against a ${money(b.planned)} plan (${fmtPct(b.spent,b.planned)}). At the current pace, spending could reach about ${money(projected)} by month-end.`,prompt:`Help me control ${b.category} spending this month`})}}});
  if(cur.earned>0&&cur.spent>cur.earned){out.push({level:'risk',title:'Cash flow is negative',detail:`Recorded expenses exceed recorded income by ${money(cur.spent-cur.earned)} for this period. Check whether this is timing-related or a recurring monthly pattern before changing commitments.`,prompt:'Help me improve my cash flow'});}
